  {
    json: {
      sourceName: 'Rockstar Games - YouTube oficial',
      sourceType: 'official',
      url: 'https://www.youtube.com/feeds/videos.xml?channel_id=UC6VcWc1rAoWdBCM0JxrRQ3A'
    }
  },
  {
    json: {
      sourceName: 'Rockstar Newswire via Google News',
      sourceType: 'official',
      url: 'https://news.google.com/rss/search?q=site%3Arockstargames.com%2Fnewswire+%22Grand+Theft+Auto+VI%22&hl=en-US&gl=US&ceid=US%3Aen'
    }
  },
  {
    json: {
      sourceName: 'Tendencias GTA VI - ultimos 2 dias',
      sourceType: 'news',
      url: 'https://news.google.com/rss/search?q=%28%22GTA+VI%22+OR+%22GTA+6%22+OR+%22Grand+Theft+Auto+VI%22%29+when%3A2d&hl=en-US&gl=US&ceid=US%3Aen'
    }
  }
];

// ViceScope Radar v2
// Classifica a fonte pelo nome do veiculo no titulo do Google News,
// elimina propaganda e assuntos paralelos, agrupa pautas repetidas
// e guarda apenas URLs que realmente seguem para a etapa editorial.
const memory = $getWorkflowStaticData('global');
const now = Date.now();
const historyTtl = 14 * 24 * 60 * 60 * 1000;
const articleTtl = 3 * 24 * 60 * 60 * 1000;
const maxCandidates = 8;

memory.seen = memory.seen || {};
for (const [key, timestamp] of Object.entries(memory.seen)) {
  if (!timestamp || now - timestamp > historyTtl) delete memory.seen[key];
}

const clean = (value = '') =>
  String(value)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ')
    .trim();

const normalizeText = (value = '') =>
  clean(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

const normalizeUrl = (value = '') => {
  try {
    const url = new URL(value);
    for (const key of [...url.searchParams.keys()]) {
      if (key.startsWith('utm_') || ['gclid', 'fbclid', 'si'].includes(key)) {
        url.searchParams.delete(key);
      }
    }
    url.hash = '';
    return url.toString();
  } catch {
    return String(value).trim();
  }
};

const extractPublisher = (title, author, description) => {
  const knownAuthor = clean(author);
  if (knownAuthor && !/google news/i.test(knownAuthor)) return knownAuthor;

  const titleMatch = title.match(/\s[-–—]\s([^–—-]{2,80})$/);
  if (titleMatch) return clean(titleMatch[1]);

  const officialInDescription = description.match(/Rockstar Games\s*$/i);
  if (officialInDescription) return 'Rockstar Games';

  return 'Fonte externa';
};

const getTopic = (text) => {
  const rules = [
    ['official-update', ['rockstar confirms', 'rockstar reveals', 'official announcement', 'newswire']],
    ['trailer', ['trailer']],
    ['release', ['release date', 'launch date', 'delay', 'delayed', 'launch']],
    ['gameplay', ['gameplay', 'gameplay footage']],
    ['leak', ['leak', 'leaked', 'cyberleek']],
    ['preorder', ['pre-order', 'preorder']],
    ['map', ['map', 'vice city']],
    ['characters', ['lucia', 'jason', 'character']],
    ['music-radio', ['soundtrack', 'radio station', 'music']],
    ['rating', ['rating', 'classification', 'esrb', 'pegi']],
    ['platforms', ['switch 2', 'pc version', 'xbox', 'playstation']],
    ['technology', ['ray tracing', 'performance', 'fps', 'graphics']],
    ['marketing', ['billboard', 'advertising', 'ads', 'marketing']],
    ['collectors', ['collector', 'collection', 'merchandise']]
  ];
  for (const [topic, terms] of rules) {
    if (terms.some(term => text.includes(term))) return topic;
  }
  return 'general';
};

const gtaPattern = /\b(gta\s*(vi|6)|grand theft auto\s*(vi|6))\b/i;
const officialPattern = /rockstar games|rockstargames\.com|rockstar newswire/i;

const strongTerms = [
  'trailer', 'gameplay', 'release date', 'delay', 'official',
  'rockstar confirms', 'rockstar reveals', 'announcement',
  'map', 'lucia', 'jason', 'vice city'
];

const rumorTerms = [
  'rumor', 'leak', 'leaked', 'allegedly', 'reportedly',
  'insider claims', 'might', 'could be', 'supposedly'
];

const junkTerms = [
  'earbuds', 'headphones', 'best price', 'deal compared',
  'cheapest', 'stock rebounds', 'shares', 'investor',
  'skyrim gets', 'take time off', 'leave on the gta',
  'holiday request', 'buy now'
];

const trustedPublishers = [
  'ign', 'gamespot', 'eurogamer', 'polygon', 'the verge',
  'rock paper shotgun', 'pc gamer', 'kotaku', 'vgc',
  'game informer', 'playstation', 'xbox'
];

const candidates = [];

for (const item of $input.all()) {
  const data = item.json || {};
  const title = clean(data.title);
  const description = clean(
    data.contentSnippet || data.content || data.summary || data.description
  );
  const url = normalizeUrl(data.link || data.guid || data.url);
  const author = clean(data.creator || data.author || data['dc:creator']);
  const publisher = extractPublisher(title, author, description);
  const text = normalizeText(`${title} ${description}`);
  const publisherText = normalizeText(publisher);

  if (!title || !url || !gtaPattern.test(text)) continue;
  if (junkTerms.some(term => text.includes(term))) continue;

  const publishedRaw = data.isoDate || data.pubDate || data.published || data.date;
  const parsedPublished = publishedRaw ? new Date(publishedRaw).getTime() : now;
  const publishedMs = Number.isFinite(parsedPublished) ? parsedPublished : now;
  if (now - publishedMs > articleTtl) continue;

  const key = url.toLowerCase().replace(/\/$/, '');
  if (memory.seen[key]) continue;

  const officialRockstar =
    officialPattern.test(publisherText) ||
    officialPattern.test(author) ||
    /\s[-–—]\s*rockstar games\s*$/i.test(title) ||
    (!url.includes('news.google.com') && /rockstargames\.com/i.test(url));

  const trusted = trustedPublishers.some(source => publisherText.includes(source));
  const ageHours = Math.max(0, (now - publishedMs) / 3600000);

  let score = officialRockstar ? 100 : trusted ? 72 : 55;
  score += strongTerms.filter(term => text.includes(term)).length * 4;
  score -= rumorTerms.filter(term => text.includes(term)).length * 6;
  score += ageHours <= 6 ? 8 : ageHours <= 24 ? 4 : 0;
  score = Math.max(0, Math.min(100, score));

  const topic = getTopic(text);
  const reliability = officialRockstar
    ? 'official'
    : trusted
      ? 'trusted_press_needs_confirmation'
      : 'needs_verification';

  candidates.push({
    radarEmpty: false,
    title,
    url,
    publisher,
    publishedAt: new Date(publishedMs).toISOString(),
    summary: description.slice(0, 650),
    topic,
    official: officialRockstar,
    reliability,
    verificationRequired: !officialRockstar,
    viralScore: score,
    _key: key
  });
}

// Mantem a melhor noticia de cada pauta. Uma publicacao oficial sempre vence
// uma repeticao da imprensa sobre o mesmo anuncio.
candidates.sort((a, b) =>
  Number(b.official) - Number(a.official) ||
  b.viralScore - a.viralScore ||
  new Date(b.publishedAt) - new Date(a.publishedAt)
);

const selected = [];
const usedTopics = new Set();

for (const candidate of candidates) {
  if (usedTopics.has(candidate.topic)) continue;
  usedTopics.add(candidate.topic);
  selected.push(candidate);
  if (selected.length >= maxCandidates) break;
}

if (selected.length === 0) {
  return [{
    json: {
      radarEmpty: true,
      status: 'Nenhuma pauta nova e qualificada sobre GTA VI nesta execucao.'
    }
  }];
}

return selected.map(candidate => {
  memory.seen[candidate._key] = now;
  delete candidate._key;
  return { json: candidate };
});

const input = $input.all();

if (input.length === 1 && input[0].json.radarEmpty) {
  return [{
    json: {
      status: 'empty',
      generatedAt: new Date().toISOString(),
      count: 0,
      officialCount: 0,
      requiresVerificationCount: 0,
      candidates: [],
      message: input[0].json.status
    }
  }];
}

const candidates = input
  .map(item => item.json)
  .filter(item => !item.radarEmpty)
  .sort((a, b) =>
    Number(b.official) - Number(a.official) ||
    b.viralScore - a.viralScore
  );

return [{
  json: {
    status: 'ready_for_editorial_ai',
    generatedAt: new Date().toISOString(),
    count: candidates.length,
    officialCount: candidates.filter(item => item.official).length,
    requiresVerificationCount: candidates.filter(item => item.verificationRequired).length,
    editorialRules: {
      doNotInventFacts: true,
      externalClaimsNeedConfirmation: true,
      preferOfficialSources: true,
      outputLanguage: 'pt-BR'
    },
    candidates
  }
}];
